require_once __DIR__.'/../includes/auth.php'; require_role('student');$uid=current_user()['id'];$id=(int)($_GET['id']??$_POST['equipment_id']??0);$s=$pdo->prepare("SELECT * FROM equipment WHERE id=?");$s->execute([$id]);$equipment=$s->fetch();if(!$equipment)exit('Equipment not found.');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$date=$_POST['booking_date'];$start=$_POST['start_time'];$end=$_POST['end_time'];$qty=(int)$_POST['quantity'];if($date<date('Y-m-d')||$end<=$start||$qty<1){flash('Check the date, time range and quantity.','danger');redirect('book-equipment.php?id='.$id);}if($equipment['condition_status']==='Under Maintenance') {flash('This equipment is under maintenance.','danger');redirect('equipment.php');}
 $pdo->prepare("INSERT INTO bookings(student_user_id,equipment_id,quantity,booking_date,start_time,end_time,purpose,status) VALUES(?,?,?,?,?,?,?,'Pending')")->execute([$uid,$id,$qty,$date,$start,$end,trim($_POST['purpose'])]);$admins=$pdo->query("SELECT id FROM users WHERE role='admin' AND is_active=1")->fetchAll();foreach($admins as $a)notify($pdo,(int)$a['id'],'New booking request submitted for '.$equipment['name'].'.');flash('Your equipment booking request has been submitted successfully. Please wait for admin approval.');redirect('my-bookings.php');}
page_header('Book Equipment','student');?>
<div class="panel"><h2 class="section-title"><?=e($equipment['name'])?></h2><p class="muted"><?=e($equipment['equipment_code'])?> · Available quantity: <?=$equipment['available_quantity']?></p><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="equipment_id" value="<?=$id?>"><div class="col-md-4"><label class="form-label">Required quantity</label><input class="form-control" type="number" name="quantity" min="1" max="<?=$equipment['quantity']?>" required></div><div class="col-md-4"><label class="form-label">Booking date</label><input class="form-control" type="date" name="booking_date" min="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><label class="form-label">Start time</label><input class="form-control" type="time" name="start_time" required></div><div class="col-md-2"><label class="form-label">End time</label><input class="form-control" type="time" name="end_time" required></div><div class="col-12"><label class="form-label">Purpose</label><textarea class="form-control" name="purpose" required></textarea></div><div class="col-12"><button class="btn btn-primary">Submit booking request</button></div></form></div><?php page_footer();?>
